package com.quincaisoft.sync;
import com.quincaisoft.sync.api.*;import com.quincaisoft.sync.application.*;import com.quincaisoft.sync.domain.*;import com.quincaisoft.identity.application.*;import com.quincaisoft.audit.application.*;import com.quincaisoft.shared.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import jakarta.persistence.*;import org.springframework.jdbc.datasource.DriverManagerDataSource;import org.springframework.orm.jpa.*;import org.springframework.orm.jpa.vendor.HibernateJpaVendorAdapter;import org.springframework.transaction.support.TransactionTemplate;import tools.jackson.databind.json.JsonMapper;import java.util.*;import java.sql.*;import java.nio.file.*;import java.security.*;import java.util.function.Supplier;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="QUINCAI_PG_TEST_URL",matches=".+")
class PostgresSyncTest{
 static void sql(Connection c,String text)throws Exception{try(var s=c.createStatement()){s.execute(text);}}
 @Test void proofApprovalRecoveryReplayAndQuarantineAreDurable()throws Exception{
 String adminUrl=System.getenv("QUINCAI_PG_TEST_URL"),adminUser=System.getenv().getOrDefault("QUINCAI_PG_TEST_USER","agent"),db="sync_test_"+UUID.randomUUID().toString().replace("-",""),role="sync_role_"+UUID.randomUUID().toString().replace("-","");String url=adminUrl.substring(0,adminUrl.lastIndexOf('/')+1)+db;
 UUID t=UUID.randomUUID(),c=UUID.randomUUID(),b=UUID.randomUUID(),a=UUID.randomUUID();
 try(var admin=DriverManager.getConnection(adminUrl,adminUser,"")){sql(admin,"CREATE ROLE "+role+" LOGIN NOSUPERUSER NOBYPASSRLS INHERIT");sql(admin,"GRANT quincai_app TO "+role);sql(admin,"CREATE DATABASE "+db);LocalContainerEntityManagerFactoryBean factory=null;
 try(var owner=DriverManager.getConnection(url,adminUser,"")){
 try(var paths=Files.list(Path.of("../../db-migrations/src/main/resources/db/migration"))){for(var file:paths.filter(p->p.toString().endsWith(".sql")).sorted(Comparator.comparingInt(p->Integer.parseInt(p.getFileName().toString().split("__")[0].substring(1)))).toList())sql(owner,Files.readString(file));}
 sql(owner,"INSERT INTO tenant(id,name)VALUES('"+t+"','Synthetic');INSERT INTO company(tenant_id,id,name)VALUES('"+t+"','"+c+"','Synthetic');INSERT INTO branch(tenant_id,company_id,id,name)VALUES('"+t+"','"+c+"','"+b+"','Synthetic');INSERT INTO tenant_memberships(tenant_id,actor_id,company_id,branch_id,role_code)VALUES('"+t+"','"+a+"','"+c+"','"+b+"','owner')");
 var ds=new DriverManagerDataSource(url,role,"");factory=new LocalContainerEntityManagerFactoryBean();factory.setDataSource(ds);factory.setJpaVendorAdapter(new HibernateJpaVendorAdapter());factory.setPackagesToScan("com.quincaisoft.sync.infrastructure","com.quincaisoft.identity.infrastructure","com.quincaisoft.audit.infrastructure");factory.setJpaPropertyMap(Map.of("hibernate.hbm2ddl.auto","validate"));factory.afterPropertiesSet();var emf=factory.getObject();var em=SharedEntityManagerCreator.createSharedEntityManager(emf);var template=new TransactionTemplate(new JpaTransactionManager(emf));
 ScopedTransactions tx=new ScopedTransactions(){public <T>T execute(Supplier<T> action){return template.execute(status->{var s=TenantContext.current();em.createNativeQuery("select set_config('app.tenant_id',:t,true),set_config('app.company_id',:c,true),set_config('app.branch_id',:b,true),set_config('app.actor_id',:a,true)").setParameter("t",s.tenantId().toString()).setParameter("c",s.companyId().toString()).setParameter("b",s.branchId().toString()).setParameter("a",s.actorId().toString()).getSingleResult();return action.get();});}};
 var identity=new DefaultIdentityService(em,tx,new DefaultAuditService(em,tx));var service=new DefaultSyncService(em,tx,identity,JsonMapper.builder().build(),new DefaultAuditService(em,tx));var scope=new TenantScope(t,c,b,a);var keys=KeyPairGenerator.getInstance("RSA");keys.initialize(2048);var pair=keys.generateKeyPair();
 TenantContext.call(scope,1,()->{var request=new SyncService.Challenge(UUID.randomUUID(),"Synthetic device",DeviceProofTest.pem(pair));var device=service.challenge(request);assertEquals(device,service.challenge(request));assertFalse(device.offlineSelling());var signed=DeviceProofTest.sign(pair,DeviceProof.enrollment(t,c,b,device.id(),device.epoch(),device.challenge()));var proved=service.prove(device.id(),new SyncService.Proof(UUID.randomUUID(),device.version(),signed));var active=service.approve(device.id(),new SyncService.Approval(UUID.randomUUID(),proved.version(),"Owner verifies synthetic device"));assertEquals("ACTIVE",active.status());assertFalse(active.offlineSelling());var source=UUID.randomUUID();String payload="{\"amountXaf\":\"1000\"}";var signature=DeviceProofTest.sign(pair,DeviceProof.recovery(t,c,b,device.id(),device.epoch(),1,source,"COMPLETED_EXCEPTION",DeviceProof.hash(payload)));var input=new SyncService.Recovery(UUID.randomUUID(),source,device.id(),device.epoch(),1,"COMPLETED_EXCEPTION",payload,signature,"Recover synthetic facts");var receipt=service.recover(input);assertEquals("REVIEW_REQUIRED",receipt.status());assertFalse(receipt.businessPosted());assertEquals(receipt,service.recover(input));var conflictingPayload="{\"amountXaf\":\"2000\"}";var conflictSignature=DeviceProofTest.sign(pair,DeviceProof.recovery(t,c,b,device.id(),device.epoch(),1,source,"COMPLETED_EXCEPTION",DeviceProof.hash(conflictingPayload)));var conflict=service.recover(new SyncService.Recovery(UUID.randomUUID(),source,device.id(),device.epoch(),1,"COMPLETED_EXCEPTION",conflictingPayload,conflictSignature,"Conflicting recovered facts"));assertEquals("CONFLICTING_HISTORY",conflict.status());assertEquals(2,service.recovery().size());assertThrows(IllegalArgumentException.class,()->service.recover(new SyncService.Recovery(UUID.randomUUID(),source,device.id(),device.epoch(),1,"COMPLETED_EXCEPTION",payload,"bad signature","Forged test")));assertEquals("ACCEPTED",service.status(input.operationId()).status());return null;});
 try(var statement=owner.createStatement();var rows=statement.executeQuery("select count(*) from journal_entry")){rows.next();assertEquals(0,rows.getInt(1));}
 TenantContext.call(new TenantScope(t,c,UUID.randomUUID(),a),1,()->{assertThrows(NoSuchElementException.class,()->service.status(UUID.randomUUID()));return null;});
 }finally{if(factory!=null)factory.destroy();sql(admin,"DROP DATABASE "+db+" WITH (FORCE)");sql(admin,"DROP ROLE "+role);}}
 }
}
